-- Admin registry bootstrap for PostgreSQL. The app's init_db() applies the
-- equivalent SQL through SQLAlchemy create_all for existing installations.
CREATE TABLE IF NOT EXISTS admin_experiences (id VARCHAR(128) PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', thumbnail_path VARCHAR(512), internal_prompt TEXT NOT NULL, provider VARCHAR(64) NOT NULL, model VARCHAR(128) NOT NULL, reference_mode VARCHAR(64) NOT NULL DEFAULT 'SINGLE_USER_IMAGE', output_format VARCHAR(16) NOT NULL DEFAULT 'PNG', status VARCHAR(16) NOT NULL DEFAULT 'draft', category VARCHAR(64) NOT NULL DEFAULT 'Design', enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_by VARCHAR(128) NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS admin_templates (id VARCHAR(128) PRIMARY KEY, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', image_path VARCHAR(512) NOT NULL, metadata_path VARCHAR(512), enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_by VARCHAR(128) NOT NULL DEFAULT 'admin');
ALTER TABLE generation_jobs ADD COLUMN IF NOT EXISTS experience_id VARCHAR(128);
